package cl.biblioteca.view;
import cl.biblioteca.controller.BibliotecaController; import cl.biblioteca.model.*; import javax.swing.*; import javax.swing.table.DefaultTableModel; import java.awt.*; import java.util.*; import java.util.List; import java.util.concurrent.*;
public class MainFrame extends JFrame {
 private final BibliotecaController c; private final JTabbedPane tabs=new JTabbedPane(); private final DefaultTableModel booksModel=model("ID","Título","Autor","ISBN","Editorial","Stock","Categoría"); private final JTable booksTable=new JTable(booksModel); private final DefaultTableModel studentsModel=model("ID","Nombre","RUT","Curso","Correo"); private final JTable studentsTable=new JTable(studentsModel); private final DefaultTableModel loansModel=model("ID","Estudiante","Libro","Préstamo","Vencimiento","Estado"); private final JTable loansTable=new JTable(loansModel);
 public MainFrame(BibliotecaController controller){c=controller;setTitle("Sistema de Gestión de Biblioteca Escolar — "+c.getUsuario().getNombre());setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1050,650);setLocationRelativeTo(null);setLayout(new BorderLayout());JLabel header=new JLabel("  BIBLIOTECA ESCOLAR     |     Sesión: "+c.getUsuario().getNombre()+" — "+c.getUsuario().getTipoPersona());header.setBorder(BorderFactory.createEmptyBorder(12,8,12,8));header.setFont(header.getFont().deriveFont(Font.BOLD,15f));add(header,BorderLayout.NORTH);tabs.addTab("Libros",panelLibros());tabs.addTab("Préstamos y devoluciones",panelPrestamos());tabs.addTab("Reportes",panelReportes());if(c.esBibliotecario())tabs.addTab("Estudiantes",panelEstudiantes());add(tabs,BorderLayout.CENTER);refrescarTodo();}
 private static DefaultTableModel model(String...cols){return new DefaultTableModel(cols,0){@Override public boolean isCellEditable(int r,int c){return false;}};}
 private JPanel basePanel(JTable table,JPanel actions){JPanel p=new JPanel(new BorderLayout(8,8));p.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));p.add(new JScrollPane(table),BorderLayout.CENTER);p.add(actions,BorderLayout.SOUTH);return p;}
 private JPanel panelLibros(){JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));if(c.esBibliotecario()){addButton(actions,"Agregar",e->editarLibro(null));addButton(actions,"Modificar seleccionado",e->editarLibro(libroSeleccionado()));addButton(actions,"Eliminar seleccionado",e->eliminarLibro());}addButton(actions,"Actualizar",e->refrescarLibros());return basePanel(booksTable,actions);}
 private JPanel panelEstudiantes(){JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));addButton(actions,"Agregar estudiante",e->editarEstudiante(null));addButton(actions,"Modificar seleccionado",e->editarEstudiante(estudianteSeleccionado()));addButton(actions,"Eliminar seleccionado",e->eliminarEstudiante());addButton(actions,"Actualizar",e->refrescarEstudiantes());return basePanel(studentsTable,actions);}
 private JPanel panelPrestamos(){JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));addButton(actions,"Registrar préstamo",e->registrarPrestamo());addButton(actions,"Registrar devolución",e->devolverPrestamo());addButton(actions,"Actualizar",e->refrescarPrestamos());JPanel p=basePanel(loansTable,actions);p.add(new JLabel("  Los préstamos vencen en 14 días. Los atrasos aparecen destacados en la columna Estado."),BorderLayout.NORTH);return p;}
 private JPanel panelReportes(){JPanel p=new JPanel(new BorderLayout(8,8));JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextArea output=new JTextArea();output.setEditable(false);output.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));buttons.add(makeButton("Libros más prestados",()->mostrar(output,()->c.masPrestados())));buttons.add(makeButton("Préstamos activos",()->{try{List<String> lines=new ArrayList<>();for(Prestamo x:c.activos())lines.add("#"+x.getId()+" | "+x.getEstudiante()+" | "+x.getLibro()+" | vence "+x.getFechaDevolucion()+(x.estaAtrasado()?" | ATRASADO":""));output.setText(lines.isEmpty()?"No hay préstamos activos.":String.join("\n",lines));}catch(Exception ex){error(ex);}}));buttons.add(makeButton("Historial por estudiante",()->{try{List<Estudiante> es=c.estudiantes();if(es.isEmpty()){info("No hay estudiantes registrados.");return;}Estudiante e=(Estudiante)JOptionPane.showInputDialog(this,"Selecciona estudiante:","Historial",JOptionPane.QUESTION_MESSAGE,null,es.toArray(),es.get(0));if(e!=null){List<String> lines=c.historial(e.getId());output.setText(lines.isEmpty()?"Sin historial para este estudiante.":String.join("\n",lines));}}catch(Exception ex){error(ex);}}));p.add(buttons,BorderLayout.NORTH);p.add(new JScrollPane(output),BorderLayout.CENTER);return p;}
 private interface ListCall{List<String> run()throws Exception;} private void mostrar(JTextArea out,ListCall call){try{List<String> l=call.run();out.setText(l.isEmpty()?"No hay datos para mostrar.":String.join("\n",l));}catch(Exception ex){error(ex);}}
 private interface Action{void run();} private JButton makeButton(String text,Action a){JButton b=new JButton(text);b.addActionListener(e->a.run());return b;} private void addButton(JPanel p,String text,java.awt.event.ActionListener a){JButton b=new JButton(text);b.addActionListener(a);p.add(b);}
 private Libro libroSeleccionado(){int row=booksTable.getSelectedRow();if(row<0){info("Selecciona un libro de la tabla.");return null;}int id=(int)booksModel.getValueAt(row,0);try{for(Libro l:c.libros())if(l.getId()==id)return l;}catch(Exception ex){error(ex);}return null;}
 private void editarLibro(Libro old){try{List<Categoria> cats=c.categorias();if(cats.isEmpty()){info("Primero debe existir al menos una categoría en MySQL.");return;}JTextField title=new JTextField(old==null?"":old.getTitulo()),author=new JTextField(old==null?"":old.getAutor()),isbn=new JTextField(old==null?"":old.getIsbn()),editorial=new JTextField(old==null?"":old.getEditorial()),stock=new JTextField(old==null?"0":String.valueOf(old.getStock()));JComboBox<Categoria> category=new JComboBox<>(cats.toArray(new Categoria[0]));if(old!=null)for(int i=0;i<cats.size();i++)if(cats.get(i).getId()==old.getIdCategoria())category.setSelectedIndex(i);JPanel form=new JPanel(new GridLayout(0,2,6,6));form.add(new JLabel("Título:"));form.add(title);form.add(new JLabel("Autor:"));form.add(author);form.add(new JLabel("ISBN único:"));form.add(isbn);form.add(new JLabel("Editorial:"));form.add(editorial);form.add(new JLabel("Stock:"));form.add(stock);form.add(new JLabel("Categoría:"));form.add(category);if(JOptionPane.showConfirmDialog(this,form,old==null?"Nuevo libro":"Editar libro",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){int st=Integer.parseInt(stock.getText().trim());if(title.getText().isBlank()||author.getText().isBlank()||isbn.getText().isBlank()||editorial.getText().isBlank()||st<0)throw new IllegalArgumentException("Completa todos los campos y usa stock no negativo.");Categoria cat=(Categoria)category.getSelectedItem();Libro b=new Libro(old==null?0:old.getId(),title.getText().trim(),author.getText().trim(),isbn.getText().trim(),editorial.getText().trim(),st,cat.getId(),cat.getNombre());c.guardarLibro(b);refrescarLibros();}}catch(Exception ex){error(ex);}}
 private void eliminarLibro(){Libro l=libroSeleccionado();if(l!=null&&JOptionPane.showConfirmDialog(this,"¿Eliminar ‘"+l.getTitulo()+"’? Si tiene préstamos asociados MySQL puede impedirlo.","Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{c.eliminarLibro(l.getId());refrescarLibros();}catch(Exception ex){error(ex);}}
 private Estudiante estudianteSeleccionado(){int row=studentsTable.getSelectedRow();if(row<0){info("Selecciona un estudiante.");return null;}int id=(int)studentsModel.getValueAt(row,0);try{for(Estudiante e:c.estudiantes())if(e.getId()==id)return e;}catch(Exception ex){error(ex);}return null;}
 private void editarEstudiante(Estudiante old){try{JTextField nombre=new JTextField(old==null?"":old.getNombre()),rut=new JTextField(old==null?"":old.getRut()),curso=new JTextField(old==null?"":old.getCurso()),correo=new JTextField(old==null?"":old.getCorreo());JPanel f=new JPanel(new GridLayout(0,2,6,6));f.add(new JLabel("Nombre:"));f.add(nombre);f.add(new JLabel("RUT:"));f.add(rut);f.add(new JLabel("Curso:"));f.add(curso);f.add(new JLabel("Correo:"));f.add(correo);if(JOptionPane.showConfirmDialog(this,f,old==null?"Nuevo estudiante":"Editar estudiante",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){if(nombre.getText().isBlank()||rut.getText().isBlank()||curso.getText().isBlank()||correo.getText().isBlank())throw new IllegalArgumentException("Completa todos los campos.");c.guardarEstudiante(new Estudiante(old==null?0:old.getId(),nombre.getText().trim(),rut.getText().trim(),curso.getText().trim(),correo.getText().trim()));refrescarEstudiantes();}}catch(Exception ex){error(ex);}}
 private void eliminarEstudiante(){Estudiante e=estudianteSeleccionado();if(e!=null&&JOptionPane.showConfirmDialog(this,"¿Eliminar a "+e.getNombre()+"?","Confirmar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{c.eliminarEstudiante(e.getId());refrescarEstudiantes();}catch(Exception ex){error(ex);}}
 private void registrarPrestamo(){try{List<Estudiante> es=c.estudiantes();List<Libro> ls=c.libros().stream().filter(l->l.getStock()>0).toList();if(es.isEmpty()||ls.isEmpty()){info("Se necesita al menos un estudiante y un libro con stock disponible.");return;}JComboBox<Estudiante> ec=new JComboBox<>(es.toArray(new Estudiante[0]));JComboBox<Libro> lc=new JComboBox<>(ls.toArray(new Libro[0]));JPanel f=new JPanel(new GridLayout(0,2,6,6));f.add(new JLabel("Estudiante:"));f.add(ec);f.add(new JLabel("Libro disponible:"));f.add(lc);if(JOptionPane.showConfirmDialog(this,f,"Registrar préstamo",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){Estudiante e=(Estudiante)ec.getSelectedItem();Libro l=(Libro)lc.getSelectedItem();setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));new SwingWorker<Void,Void>(){protected Void doInBackground()throws Exception{c.registrarPrestamo(e.getId(),l.getId()).get();return null;}protected void done(){setCursor(Cursor.getDefaultCursor());try{get();info("Préstamo registrado. Fecha de vencimiento: 14 días desde hoy.");refrescarTodo();}catch(Exception ex){error(ex.getCause()==null?ex:ex.getCause());}}}.execute();}}catch(Exception ex){error(ex);}}
 private void devolverPrestamo(){int row=loansTable.getSelectedRow();if(row<0){info("Selecciona el préstamo en la tabla.");return;}int id=(int)loansModel.getValueAt(row,0);String state=String.valueOf(loansModel.getValueAt(row,5));if(state.startsWith("Devuelto")){info("Ese préstamo ya fue devuelto.");return;}if(JOptionPane.showConfirmDialog(this,"¿Registrar devolución del préstamo #"+id+"?","Confirmar devolución",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{c.devolver(id);refrescarTodo();info("Devolución registrada y stock actualizado.");}catch(Exception ex){error(ex);}}
 private void refrescarTodo(){refrescarLibros();refrescarEstudiantes();refrescarPrestamos();} private void refrescarLibros(){try{booksModel.setRowCount(0);for(Libro l:c.libros())booksModel.addRow(new Object[]{l.getId(),l.getTitulo(),l.getAutor(),l.getIsbn(),l.getEditorial(),l.getStock(),l.getCategoria()});}catch(Exception ex){error(ex);}} private void refrescarEstudiantes(){try{studentsModel.setRowCount(0);for(Estudiante e:c.estudiantes())studentsModel.addRow(new Object[]{e.getId(),e.getNombre(),e.getRut(),e.getCurso(),e.getCorreo()});}catch(Exception ex){error(ex);}} private void refrescarPrestamos(){try{loansModel.setRowCount(0);for(Prestamo p:c.prestamos()){String estado=p.isDevuelto()?"Devuelto":p.estaAtrasado()?"ATRASADO":"Pendiente";loansModel.addRow(new Object[]{p.getId(),p.getEstudiante(),p.getLibro(),p.getFechaPrestamo(),p.getFechaDevolucion(),estado});}for(int i=0;i<loansTable.getRowCount();i++)if(String.valueOf(loansModel.getValueAt(i,5)).equals("ATRASADO"))loansTable.setValueAt("ATRASADO ⚠",i,5);}catch(Exception ex){error(ex);}}
 private void info(String s){JOptionPane.showMessageDialog(this,s,"Biblioteca Escolar",JOptionPane.INFORMATION_MESSAGE);}private void error(Throwable e){String msg=e.getMessage()==null?e.toString():e.getMessage();JOptionPane.showMessageDialog(this,msg,"Error",JOptionPane.ERROR_MESSAGE);}
}
